// Normalize inputs, set defaults, compute output size and bg hex
const item = items[0];
const body = item.json || {};
const pose = (body.pose || 'LOOK_CAMERA').toUpperCase();
const orientation = (body.orientation || 'landscape').toLowerCase();
const seed = Number.isInteger(body.seed) ? body.seed : 1337;
const outWidth = orientation === 'portrait' ? 1536 : 2048;
const outHeight = orientation === 'portrait' ? 2048 : 1536;
const forceSwap = !!body.forceSwap; // allow manual override

item.json.meta = {
  pose,
  orientation,
  seed,
  outWidth,
  outHeight,
  forceSwap,
  bgHex: $env.APP_BG_HEX || '#014431',
};

// Support both image_url and uploaded binary. If uploaded, store property name.
// n8n's Webhook binary property name defaults to 'data' if 'binaryData: true'.
if (item.binary && item.binary.data) {
  item.json.sourceType = 'binary';
  item.json.binaryProperty = 'data';
} else if (body.image_url) {
  item.json.sourceType = 'url';
  item.json.image_url = body.image_url;
} else {
  // Expect a URL; you can also add a prior node to fetch remote file into binary.
  throw new Error('Provide image_url in JSON body or upload a file in form-data "data".');
}

return items;

const meta = $json.meta || {};
const r = $json; // The HTTP node puts response JSON as root

// Best-effort parsing (adjust to match AILabTools schema)
const subject = {
  hair: { length: r?.data?.hair?.length || r?.hair?.length || null,
          color:  r?.data?.hair?.color  || r?.hair?.color  || null,
          texture:r?.data?.hair?.texture|| r?.hair?.texture|| null },
  eyes: { color: r?.data?.eye?.color || r?.eye?.color || null,
          shape: r?.data?.eye?.shape || r?.eye?.shape || null },
  eyebrows: { thickness: r?.data?.eyebrow?.thickness || r?.eyebrow?.thickness || null,
              shape:     r?.data?.eyebrow?.shape     || r?.eyebrow?.shape     || null },
  skin: { tone: r?.data?.skin?.tone || r?.skin?.tone || null,
          texture: r?.data?.skin?.texture || r?.skin?.texture || null },
  facial_hair: r?.data?.beard?.type || r?.beard?.type || 'clean-shaven',
  marks: (r?.data?.marks || r?.marks || []).slice(0,3),
  accessories: {
    glasses: r?.data?.eye?.glass || r?.eye?.glass || 'none', // none|regular|sunglasses
    mask: r?.data?.mask || r?.mask || 'none',
    headwear: (r?.data?.hat?.style || r?.hat?.style) ? 'headwear' : 'none',
    headwearColor: r?.data?.hat?.color || r?.hat?.color || null,
  }
};

// Hijab/Headscarf fallback (very naive keyword match if description exists)
if (typeof r?.description === 'string') {
  const d = r.description.toLowerCase();
  if (/(hijab|headscarf|head scarf|shayla|khimar)/.test(d)) {
    subject.accessories.headwear = 'headscarf';
  }
}

const pose = meta.pose === 'NO_LOOK'
  ? 'loose close-up, 3/4 profile, gaze off-camera, shoulders gently angled'
  : 'loose close-up, front-facing, direct eye contact, neutral professional expression';

const acc = subject.accessories || {};
const accText = [
  acc.headwear === 'headscarf' ? 'wearing a headscarf that covers the hair' :
  (acc.headwear !== 'none' ? 'wearing headwear' : null),
  acc.glasses === 'regular' ? 'wearing thin rectangular eyeglasses' :
  (acc.glasses === 'sunglasses' ? 'wearing sunglasses' : null),
  acc.mask !== 'none' ? 'wearing a face mask' : null
].filter(Boolean).join(', ');

const subjectStr = [
  `${subject.hair.length||''} ${subject.hair.color||''} ${subject.hair.texture||''} hair`.trim(),
  `${subject.eyebrows.thickness||''} ${subject.eyebrows.shape||''} eyebrows`.trim(),
  `${subject.eyes.color||''} ${subject.eyes.shape||''} eyes`.trim(),
  `${subject.skin.tone||''} ${subject.skin.texture||''} skin`.trim(),
  subject.facial_hair || 'clean-shaven',
  accText
].filter(Boolean).join(', ');

const prompt = `Single-person portrait, ${pose}. Subject exactly matches: ${subjectStr}. ` +
               `Studio lighting: soft key at 45°, gentle fill; realistic skin texture; chest-up framing; 4:3; natural color. ` +
               `Background: plain neutral temporary background (will be replaced).`;

return [{
  json: {
    subject,
    meta,
    generation: {
      prompt,
      seed: meta.seed,
      width: meta.outWidth,
      height: meta.outHeight
    },
    // pass through source info from first item in execution
    sourceType: $items(0)[0].json.sourceType,
    image_url:  $items(0)[0].json.image_url,
    binaryProperty: $items(0)[0].json.binaryProperty
  }
}];

// Normalize provider response to {gen_image_url or gen_image_b64}
const r = items[0].json;
// Try common shapes:
let url = r?.data?.[0]?.url || r?.output?.[0] || r?.image_url || null;
let b64 = r?.data?.[0]?.b64_json || r?.image_base64 || null;
return [{
  json: {
    ...$items(1)[0].json, // carry forward subject/meta/etc from Map node (index 1 back)
    gen: { url, b64, provider: 'together/flux-schnell' }
  }
}];

const it = items[0].json;
// Basic heuristic: honor meta.forceSwap flag; otherwise, swap if accessories suggest headwear or glasses (to better lock identity).
const headwear = it.subject?.accessories?.headwear || 'none';
const glasses = it.subject?.accessories?.glasses || 'none';
const should = it.meta.forceSwap || headwear !== 'none' || glasses !== 'none';
return [{ json: { ...it, shouldSwap: should } }];

const it = items[0].json;
// Prefer swapped image url if present, else generated url
let portrait_url = it?.output?.url || it?.result?.url || it?.gen?.url || null;
// Some providers return base64; if so, keep in json for downstream (remove.bg accepts URL or file).
let portrait_b64 = it?.output?.b64 || it?.result?.b64 || it?.gen?.b64 || null;
return [{ json: { ...it, portrait: { url: portrait_url, b64: portrait_b64 } } }];
